import{_ as a,o as s,c as o,a0 as n}from"./chunks/framework.jwovEGr5.js";const m=JSON.parse('{"title":"VitePress学习小记","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"理论学习/VitePress学习.md","filePath":"理论学习/VitePress学习.md"}'),p={name:"理论学习/VitePress学习.md"};function t(d,e,i,c,r,l){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="vitepress学习小记" tabindex="-1">VitePress学习小记 <a class="header-anchor" href="#vitepress学习小记" aria-label="Permalink to &quot;VitePress学习小记&quot;">​</a></h1><h2 id="vitepress介绍" tabindex="-1">VitePress介绍 <a class="header-anchor" href="#vitepress介绍" aria-label="Permalink to &quot;VitePress介绍&quot;">​</a></h2><p>VitePress是一个由Vite和Vue驱动的静态网站生成器，旨在快速构建以内容为中心的网站。它可以将用Markdown编写的内容转换为优雅的文档，生成静态HTML页面，方便部署到任何地方。（官网）</p><h2 id="我的探索" tabindex="-1">我的探索 <a class="header-anchor" href="#我的探索" aria-label="Permalink to &quot;我的探索&quot;">​</a></h2><h3 id="添加图片" tabindex="-1">添加图片 <a class="header-anchor" href="#添加图片" aria-label="Permalink to &quot;添加图片&quot;">​</a></h3><blockquote><p>相对路径方法</p></blockquote><h5 id="文件夹管理" tabindex="-1">文件夹管理 <a class="header-anchor" href="#文件夹管理" aria-label="Permalink to &quot;文件夹管理&quot;">​</a></h5><p>文件越做越多，因此我们需要管理我们的图片文件夹，以防越来越乱</p><p>示例：在你的<code>docs</code>文件夹内部添加<code>img</code>文件夹（代表图片）</p><p>此时你的目录结构参考如下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目根目录</span></span>
<span class="line"><span>├─ docs/</span></span>
<span class="line"><span>│  ├─ img/        # 专门存放文章图片</span></span>
<span class="line"><span>│  │  ├─ 1.png</span></span>
<span class="line"><span>│  │  └─ 2.jpg</span></span>
<span class="line"><span>│  ├─ articles/      # 你的文章md文件夹</span></span>
<span class="line"><span>│  │  └─ 1.md</span></span>
<span class="line"><span>│  └─ index.md       # 首页</span></span>
<span class="line"><span>└─ package.json</span></span></code></pre></div><h5 id="md添加图片" tabindex="-1"><code>.md</code>添加图片 <a class="header-anchor" href="#md添加图片" aria-label="Permalink to &quot;\`.md\`添加图片&quot;">​</a></h5><p>复习：Markdown的图片添加为<code>![图片替代文字](路径)</code></p><p>路径规则和HTML是一样的，<code>../</code>代表父级，<code>./</code>代表同级，<code>/</code>代表子级</p><p>根据当前<code>.md</code>文件位置反推图片位置即可</p><p>我们只需要先“到达”共同文件夹，然后一级一级往下找到我们的图片文件</p><p>以上文为例，<code>1.md</code>文件内添加<code>1.png</code>文件</p><ol><li><p>我们知道他们的共同文件夹是<code>docs</code>，所以先用<code>../</code>从<code>1.md</code>所在文件夹<code>articles</code>进入<code>docs</code></p></li><li><p>下一级文件<code>img</code>，再下一级为<code>1.png</code></p></li></ol><p>所以我们的路径就有了：<code>../img/1.png</code></p><h3 id="图片格式设置" tabindex="-1">图片格式设置 <a class="header-anchor" href="#图片格式设置" aria-label="Permalink to &quot;图片格式设置&quot;">​</a></h3><p>MarkDown语法本身不支持图片格式的设置，但是在VitePress当中是可以进行修改的</p><p>原生样式：<code>![图片替代文字](路径)</code></p><p>我们在后方添加<code>{}</code>，内部加上我们需要的格式</p><p>例如：<code>![图片替代文字](路径){width=400px}</code>，这样就设置了图片的宽度</p><blockquote><p>暂时只发现了width的用法，连height都用不了</p></blockquote><h2 id="vitepress其他" tabindex="-1">VitePress其他 <a class="header-anchor" href="#vitepress其他" aria-label="Permalink to &quot;VitePress其他&quot;">​</a></h2><p>VitePress支持直接在index.md里写完整Vue模板，关闭默认首页布局，用纯Vue+CSS写整个仪表盘页面，不用修改.vitepress/theme主题文件。</p><p>details: Lorem ipsum dolor sit amet, consectetur adipiscing elit是VitePress模板自带的示例占位描述，是无实义填充文本。</p>`,28)])])}const u=a(p,[["render",t]]);export{m as __pageData,u as default};
